{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Sound Bath Immersion</title>
  <meta name="description" content="A sensory, premium sound bath in {{CITY}}, {{STATE}}. Deeply relaxing group sessions and private work with {{FACILITATOR_NAME}}." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="zen">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/events.html">Circle</a>
        <a href="/private-sessions.html">Gatherings</a>
        <a href="/pricing.html">Rates</a>
        <a href="/about.html">Our Story</a>
        <a href="/faq.html">Q&amp;A</a>
        <a href="/book.html" class="cta-link">{{PRIMARY_CTA_LABEL}}</a>
        <button class="nav-toggle" aria-label="Toggle menu">☰</button>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="eyebrow">Soften. Listen. Melt.</h1>
          <h2 class="title">An immersive sound bath with {{FACILITATOR_NAME}} — a guided sensory journey in {{CITY}}.</h2>
          <p class="lead">Sink into layered harmonics: crystal bowls, monochord bass, shimmering chimes and subtle tuning forks create a plush field for rest and renewal. Sessions are intentionally limited for intimacy.</p>
          <div class="hero-cta">
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn btn-ghost" href="/events.html">Next event — {{NEXT_EVENT_DATE}}</a>
          </div>
          <p class="micro">Venue: {{VENUE_NAME}} • Small circles • Please arrive 10 min early</p>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg class="visual-wave" viewBox="0 0 600 400" preserveAspectRatio="none">
            <defs>
              <linearGradient id="g" x1="0" x2="1">
                <stop offset="0" stop-color="#f6f2ff" />
                <stop offset="1" stop-color="#eef7ff" />
              </linearGradient>
              <filter id="soft">
                <feGaussianBlur stdDeviation="12" />
              </filter>
            </defs>
            <rect width="600" height="400" fill="url(#g)" />
            <g fill="#dfe7ff" opacity="0.85" filter="url(#soft)">
              <circle cx="120" cy="140" r="90" />
              <circle cx="360" cy="200" r="120" />
              <ellipse cx="480" cy="80" rx="140" ry="40" />
            </g>
            <g fill="none" stroke="#b6c7ff" stroke-width="2" opacity="0.6">
              <path d="M0 300 C150 200 450 400 600 300" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC -->
    <section class="diagnostic wrap" id="diagnostic">
      <header class="section-head">
        <h3>Is this right for you?</h3>
        <p class="section-sub">A quick sense-check to help you choose the right offering.</p>
      </header>
      <div class="cards">
        <div class="card">
          <h4>You'll love it if…</h4>
          <ul>
            <li>You crave deep rest and a pause from thinking.</li>
            <li>You respond to vibration and rich, layered sound.</li>
            <li>You want an intentional, non-religious relaxation practice.</li>
          </ul>
        </div>
        <div class="card">
          <h4>What to bring</h4>
          <ul>
            <li>A yoga mat or cushion, and a blanket for warmth.</li>
            <li>An eye mask or scarf to block light.</li>
            <li>Water and an open-hearted intention.</li>
          </ul>
        </div>
        <div class="card">
          <h4>Contraindications</h4>
          <p class="muted">If you are pregnant, have an active epilepsy diagnosis, recent head injury, or use a pacemaker, please consult your healthcare provider before attending. Sound can be powerful — reach out if you have concerns: {{EMAIL}}</p>
        </div>
      </div>
    </section>

    <!-- PLAN (FLOW) -->
    <section class="plan" id="plan">
      <div class="wrap">
        <header class="section-head">
          <h3>The flow</h3>
          <p class="section-sub">A soft, intentional sequence to arrive and integrate.</p>
        </header>
        <ol class="flow">
          <li><strong>Arrival &amp; Grounding</strong> — Gentle breathwork and a short check-in to set an intention.</li>
          <li><strong>Resonance Build</strong> — Tones layer in: crystal singing bowls and warm monochord create a foundation.</li>
          <li><strong>Deep Field</strong> — Gong and chimes weave through tuning forks and harmonic overtones for embodied surrender.</li>
          <li><strong>Return</strong> — Soft vocal tones, silence, and time to journal or share if you wish.</li>
        </ol>
        <p class="instruments">Instruments we often use: crystal bowls, monocord, vintage gong, handheld chimes, and a selection of Tibetan bells and tuning forks — arranged to support a spacious, tactile sonic palette.</p>
      </div>
    </section>

    <!-- MICRO_HABITS -->
    <section class="micro-habits wrap" id="micro_habits">
      <header class="section-head">
        <h3>Tiny rituals that amplify the experience</h3>
        <p class="section-sub">Small practices to try before and after sessions.</p>
      </header>
      <div class="habits">
        <article>
          <h4>Pre-session</h4>
          <ul>
            <li>Hydrate steadily during the day.</li>
            <li>Softly limit caffeine for a few hours prior.</li>
            <li>Set a single-word intention — write it down if you like.</li>
          </ul>
        </article>
        <article>
          <h4>Aftercare</h4>
          <ul>
            <li>Move slowly for 20–30 minutes; stretching helps integrate sound into the body.</li>
            <li>Rest with warm tea and low light; journal any impressions.</li>
            <li>Space your next session 2–4 weeks to notice cumulative shifts.</li>
          </ul>
        </article>
      </div>
    </section>

    <!-- PRICING -->
    <section class="pricing wrap" id="pricing">
      <header class="section-head">
        <h3>Offerings &amp; investment</h3>
        <p class="section-sub">Carefully curated, small circles and bespoke private work.</p>
      </header>
      <div class="price-grid">
        <div class="price-card">
          <h4>Group Session</h4>
          <p class="price">$35</p>
          <p class="desc">60–75 min • Intimate circle • Perfect for first-timers</p>
          <a class="btn" href="/events.html">See dates</a>
        </div>
        <div class="price-card featured">
          <h4>Private 1:1</h4>
          <p class="price">$160</p>
          <p class="desc">90 min • Tailored sound journey • Deep one-on-one facilitation</p>
          <a class="btn btn-primary" href="/private-sessions.html">Book a session</a>
        </div>
        <div class="price-card">
          <h4>Couples / Duet</h4>
          <p class="price">$220</p>
          <p class="desc">A shared session to harmonize two people in resonance.</p>
          <a class="btn" href="/private-sessions.html">Learn more</a>
        </div>
      </div>
      <p class="muted small">Corporate and bespoke sound experiences available on request. Payment details and cancellation policy at booking.</p>
    </section>

    <!-- CALL TO ACTION -->
    <section class="cta wrap" id="cta">
      <div class="cta-inner">
        <h3>Ready to slow down?</h3>
        <p>Reserve your spot or request private work with {{FACILITATOR_NAME}}. Small groups fill quickly.</p>
        <div class="cta-actions">
          <a class="btn btn-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="link" href="/contact.html">Contact: {{EMAIL}}</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">{{TAGLINE}}</p>
      </div>
      <div class="foot-right">
        <p class="muted">Call: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <small class="muted">© {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</small>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
