{"path":"assets/css/styles.css","content":"/* Zen Minimal — playful premium palette */
:root{
  --bg:#fbfbfd; --card:#ffffff; --muted:#6b7280; --accent:#6b46c1; --accent-2:#7dd3fc; --glass:rgba(255,255,255,0.65);
  --radius:14px; --gap:24px; --max:1100px; --shadow:0 6px 30px rgba(16,24,40,0.08);
}
*{box-sizing:border-box}
html,body{height:100%}
body.zen{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; background:
  linear-gradient(180deg,rgba(234,241,255,0.6),rgba(255,255,255,0.95)), url('../img/pattern.svg') no-repeat center/cover; color:#0b1220; margin:0; -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:32px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.72),rgba(255,255,255,0.55));border-bottom:1px solid rgba(11,18,32,0.04)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.05rem}
.main-nav{display:flex;gap:14px;align-items:center}
.main-nav a{color:#0b1220;text-decoration:none;padding:8px 12px;border-radius:10px}
.main-nav .cta-link{background:linear-gradient(90deg,var(--accent),#9b5cf6);color:white}
.nav-toggle{display:none;background:none;border:none;font-size:18px}
.hero{padding:48px 0}
.hero-inner{display:grid;grid-template-columns:1fr 420px;gap:var(--gap);align-items:center}
.hero-copy .eyebrow{color:var(--accent);font-weight:700;margin:0}
.hero-copy .title{font-size:clamp(1.6rem,2.6vw,2.4rem);margin:.25rem 0}
.lead{color:var(--muted);margin:0 0 16px}
.hero-cta{display:flex;gap:12px;margin:18px 0}
.btn{display:inline-block;padding:10px 16px;border-radius:12px;text-decoration:none;border:1px solid rgba(11,18,32,0.06);background:var(--card);color:var(--accent);box-shadow:var(--shadow)}
.btn-primary{background:linear-gradient(90deg,var(--accent),#9b5cf6);color:white;border:0}
.btn-ghost{background:transparent;border:1px solid rgba(11,18,32,0.06)}
.btn-cta{padding:14px 20px;border-radius:16px;background:linear-gradient(90deg,#6b46c1,#7dd3fc);color:white;border:0}
.micro{color:var(--muted);font-size:.9rem}
.hero-visual{border-radius:18px;overflow:hidden;box-shadow:var(--shadow);height:260px}
.visual-wave{width:100%;height:100%}
.section-head h3{margin:0;font-size:1.05rem;color:#0b1220}
.section-sub{color:var(--muted);margin-top:6px}
.diagnostic .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:18px}
.card{background:linear-gradient(180deg,var(--glass),rgba(255,255,255,0.6));padding:18px;border-radius:14px;box-shadow:0 8px 24px rgba(15,23,42,0.04)}
.card h4{margin:0 0 6px}
.card ul{margin:8px 0 0;padding-left:18px;color:var(--muted)}
.plan .flow{margin:18px 0 8px;padding-left:18px;color:var(--muted)}
.instruments{color:var(--muted);font-size:.95rem}
.micro-habits .habits{display:flex;gap:18px;flex-wrap:wrap}
.micro-habits article{flex:1 1 260px;background:var(--card);padding:14px;border-radius:12px}
.pricing .price-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin:18px 0}
.price-card{background:linear-gradient(180deg,#fff,#fbfbff);padding:18px;border-radius:12px;text-align:center;border:1px solid rgba(11,18,32,0.04)}
.price-card.featured{transform:translateY(-6px);box-shadow:0 14px 40px rgba(11,18,32,0.08)}
.price{font-size:1.6rem;color:var(--accent);margin:8px 0}
.muted{color:var(--muted)}
.small{font-size:.85rem}
.cta{margin:36px 0;padding:22px;background:linear-gradient(180deg,rgba(107,70,193,0.06),rgba(125,211,252,0.04));border-radius:14px}
.cta-inner{text-align:center}
.cta-actions{display:flex;gap:10px;justify-content:center;align-items:center;margin-top:12px}
.site-footer{padding:22px 0;background:transparent;border-top:1px solid rgba(11,18,32,0.04)}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.foot-left strong{color:var(--accent)}
@media (max-width:900px){
  .hero-inner{grid-template-columns:1fr;}
  .main-nav a{display:none}
  .nav-toggle{display:inline-block}
  .site-header .wrap{gap:8px}
}
/* subtle focus state */
a:focus{outline:3px solid rgba(107,70,193,0.12);outline-offset:3px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple nav toggle
  var btn=document.querySelector('.nav-toggle');
  var nav=document.querySelector('.main-nav');
  btn&&btn.addEventListener('click',function(){
    if(nav.classList.contains('open')){
      nav.classList.remove('open');
      btn.innerText='☰';
    }else{
      nav.classList.add('open');
      btn.innerText='✕';
    }
  });

  // Smooth scroll for CTA links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var t=document.querySelector(this.getAttribute('href'));
      if(t) t.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });

  // Insert NEXT_EVENT_DATE into elements that link to events
  document.querySelectorAll('a[href="/events.html"]').forEach(function(a){
    var next='{{NEXT_EVENT_DATE}}';
    if(next && next.indexOf('{')===-1){
      // only replace if placeholder appears filled in server side
      a.innerText = 'Next event — '+next;
    }
  });

  // tiny accessibility: add aria-expanded on toggle
  if(btn){
    btn.setAttribute('aria-expanded','false');
    btn.addEventListener('click',function(){
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!expanded));
    });
  }
})();
"} 
